    foreach (var p in paths)
        if (File.Exists(p)) return ctx.LoadFromAssemblyPath(p);
    return null;
};

var asm = AssemblyLoadContext.Default.LoadFromAssemblyPath($"{basePath}xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll");
