using System.Reflection;

var basePath = "/home/runner/.nuget/packages/";
var resolver = new PathAssemblyResolver(new[] {
    $"{basePath}xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll",
    $"{basePath}xunit.v3.common/1.1.0/lib/netstandard2.0/xunit.v3.common.dll",
    typeof(object).Assembly.Location,
    Path.Combine(Path.GetDirectoryName(typeof(object).Assembly.Location)!, "netstandard.dll"),
});
using var mlc = new MetadataLoadContext(resolver);
var asm = mlc.LoadFromAssemblyPath($"{basePath}xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll");

foreach (var t in asm.GetTypes().Where(t => t.IsPublic).OrderBy(x => x.Name))
{
    if (t.Name.Contains("CollectionBehavior") || t.Name.Contains("TestCaseOrderer"))
        Console.WriteLine(t.FullName);
}
Console.WriteLine("\n--- CollectionBehaviorAttribute ---");
var cba = asm.GetTypes().First(t => t.Name == "CollectionBehaviorAttribute");
foreach (var c in cba.GetConstructors())
    Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
foreach (var p in cba.GetProperties(BindingFlags.Public | BindingFlags.Instance))
    Console.WriteLine($"  prop: {p.PropertyType.Name} {p.Name}");

Console.WriteLine("\n--- TestCaseOrdererAttribute ---");
var tco = asm.GetTypes().FirstOrDefault(t => t.Name == "TestCaseOrdererAttribute");
if (tco != null) {
    foreach (var c in tco.GetConstructors())
        Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var p in tco.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  prop: {p.PropertyType.Name} {p.Name}");
}
EOF
